export function collides(x,z,boxes,r=.28){return boxes.some(b=>x+r>b.x-b.w/2&&x-r<b.x+b.w/2&&z+r>b.z-b.d/2&&z-r<b.z+b.d/2)}
export function wallsFor(houses){let b=[];for(let h of houses){b.push({x:h.x-3,z:h.z,w:.25,d:6.2},{x:h.x+3,z:h.z,w:.25,d:6.2},{x:h.x,z:h.z-3,w:6,d:.25},{x:h.x-2,z:h.z+3,w:2,d:.25},{x:h.x+2,z:h.z+3,w:2,d:.25});if(!h.doorOpen&&!h.broken)b.push({x:h.x,z:h.z+3,w:1.9,d:.25});b.push({x:h.x-1.6,z:h.z-1.2,w:1.3,d:2.2},{x:h.x+1.5,z:h.z-1.9,w:1.4,d:.8});for(let t of h.turrets)b.push({x:t.x,z:t.z,w:.6,d:.6})}return b}
export function slide(pos,dx,dz,boxes,limit=19){let x=pos.x,z=pos.z;if(Math.hypot(x+dx,z)<limit&&!collides(x+dx,z,boxes))x+=dx;if(Math.hypot(x,z+dz)<limit&&!collides(x,z+dz,boxes))z+=dz;return{x,z}}
export function pathfind(start,end,boxes){const step=.65,key=(x,z)=>x+','+z,s=[Math.round(start.x/step),Math.round(start.z/step)],goal=[Math.round(end.x/step),Math.round(end.z/step)],q=[s],seen=new Set([key(...s)]),prev=new Map();let found=null;for(let k=0;k<q.length&&k<6000;k++){let [x,z]=q[k];if(Math.hypot(x-goal[0],z-goal[1])<1.3){found=[x,z];break}for(let [dx,dz] of [[1,0],[-1,0],[0,1],[0,-1]]){let a=x+dx,b=z+dz,id=key(a,b);if(seen.has(id)||Math.hypot(a*step,b*step)>19.5||collides(a*step,b*step,boxes,.3))continue;seen.add(id);prev.set(id,[x,z]);q.push([a,b])}}if(!found)return[];let out=[],p=found;while(key(...p)!==key(...s)){out.unshift({x:p[0]*step,z:p[1]*step});p=prev.get(key(...p));if(!p)break}out.push({x:end.x,z:end.z});return out}
